        ph42.record(_v42, [_mit42[_v42]['neu'][0], 'Testwaffe A'])
        pruefe(len(ph42.load()[_v42]['neu']) == _vorher42 + 3,
               'bekannte Namen kommen nicht ein zweites Mal hinein')

