    # den eigenen Bestand. Solange das stimmt, bleibt keine Luecke offen.
    pruefe(_sicher105 + _unklar105 == len(_bestand105),
           'sicher + unklar = Bestand (%d + %d = %d)'
           % (_sicher105, _unklar105, len(_bestand105)))
